window.AUTH=window.AUTH||{};window.AUTH["23-1067"]={"d":"23-1067","id":"2024/23-1067","n":"Oklahoma v. Environmental Protection Agency","briefs":[{"k":"petitioner","label":"Brief of petitioners Oklahoma, et al. (as to 23-1067)","date":"2024-12-13","url":"https://www.supremecourt.gov/DocketPDF/23/23-1067/335139/20241213171658376_No.%2023-1067-1068%20-%20Brief%20for%20Petitioners.pdf","side":"pet","n":87},{"k":"petitioner","label":"Brief of petitioners PacifiCorp, et al. (as to 23-1068)","date":"2024-12-13","url":"https://www.supremecourt.gov/DocketPDF/23/23-1067/335080/20241213134357823_23-1067%20Brief%20for%20Petitioners.pdf","side":"pet","n":43},{"k":"respondent","label":"Brief of respondents EPA, et al.","date":"2025-01-17","url":"https://www.supremecourt.gov/DocketPDF/23/23-1067/339665/20250117190406104_23-1067bsUnitedStates.pdf","side":"res","n":68},{"k":"reply","label":"Reply of petitioners Oklahoma, et al.","date":"2025-02-18","url":"https://www.supremecourt.gov/DocketPDF/23/23-1067/343059/20250218161033128_23-1067_Brief.pdf","side":"pet","n":30},{"k":"reply","label":"Reply of petitioners PacifiCorp, et al.","date":"2025-02-18","url":"https://www.supremecourt.gov/DocketPDF/23/23-1067/343017/20250218135737629_23-1068%20Reply%20Brief.pdf","side":"pet","n":27}],"opinion":"https://www.supremecourt.gov/opinions/24pdf/605us2r49_pok0.pdf","tr":true,"items":[{"t":"case","label":"Alabama Env’t Council v. EPA","cite":"711 F.3d 1277","y":2013,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/711/1277/","by":{"0":"28"}},{"t":"case","label":"Am. Rd. & Transp. Builders Ass’n v. EPA","cite":"705 F.3d 453","y":2013,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/705/453/","by":{"0":"1, 16, 24, 33, 35, 43","1":"1, 2, 10, 24, 26, 32, 33, 34, 35, 37, 45, 48, 55, 56","2":"19, 25","3":"3","4":"1, 14, 15, 21"},"q":[{"src":"brief","b":0,"text":"prototypical ‘locally or regionally applicable’ action","cite":"705 F.3d at 455"},{"src":"brief","b":0,"text":"applies a broad regulation to a specific context and … may set a precedent for future [state implementation plan] proceedings.","cite":"705 F.3d at 456"},{"src":"brief","b":1,"text":"otherwise locally or regionally applicable regulations have a nationwide scope or effect.","cite":"705 F.3d at 455"},{"src":"brief","b":1,"text":"the prototypical locally or regionally applicable action","cite":"705 F.3d at 455"},{"src":"brief","b":3,"text":"prototypical ‘locally or regionally applicable’ action that may be challenged only in the appropriate regional court of appeals.","cite":"705 F.3d 453, 455"},{"src":"brief","b":4,"text":"otherwise locally or regionally applicable regulations [that] have a nationwide scope or effect.","cite":"705 F.3d at 455"}]},{"t":"case","label":"Ass’n of Irritated Residents v. EPA","cite":"686 F.3d 668","y":2012,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/686/668/","by":{"0":"28"}},{"t":"case","label":"ATK Launch Sys., Inc. v. EPA","cite":"651 F.3d 1194","y":2011,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/651/1194/","by":{"0":"24","1":"24, 33, 35","2":"19, 24, 30"}},{"t":"case","label":"Barnhart v. Thomas","cite":"540 U.S. 20","y":2003,"id":"2003/02-763","sc":1,"by":{"0":"38"}},{"t":"case","label":"BCCA Appeal Grp. v. EPA","cite":"355 F.3d 817","y":2003,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/355/817/","by":{"0":"28"}},{"t":"case","label":"Bissonnette v. LePage Bakeries Park St., LLC","cite":"601 U.S. 246","y":2024,"id":"2023/23-51","sc":1,"by":{"0":"25"}},{"t":"case","label":"Brown Express, Inc. v. United States","cite":"607 F.2d 695","y":1979,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/607/695/","by":{"0":"30"}},{"t":"case","label":"Chevron U.S.A. Inc. v. EPA","cite":"45 F.4th 380","y":2022,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.4th/45/380/","by":{"0":"23, 32","2":"26","3":"13"},"q":[{"src":"brief","b":3,"text":"that kind of interpretive exercise alone does not transform a locally applicable action into a nationally applicable one.","cite":"45 F.4th 380, 387"}]},{"t":"case","label":"Comm. for a Better Arvin v. EPA","cite":"786 F.3d 1169","y":2015,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/786/1169/","by":{"0":"28"}},{"t":"case","label":"Cuomo v. Clearing House Ass’n, LLC","cite":"557 U.S. 519","y":2009,"id":"2008/08-453","sc":1,"by":{"0":"41","1":"47"}},{"t":"case","label":"E.I. du Pont de Nemours & Co. v. Train","cite":"430 U.S. 112","y":1977,"id":"1976/75-978","sc":1,"by":{"0":"55"},"q":[{"src":"brief","b":0,"text":"‘wisdom’ in ‘allowing difficult issues to mature through full consideration’ by different courts.","cite":"430 U.S. 112, 135 n.26"}]},{"t":"case","label":"Encino Motorcars, LLC v. Navarro","cite":"579 U.S. 211","y":2016,"id":"2015/15-415","sc":1,"by":{"0":"32-33"}},{"t":"case","label":"EPA v. EME Homer City Generation, L.P.","cite":"572 U.S. 489","y":2014,"id":"2013/12-1182","sc":1,"by":{"0":"4","2":"5, 6, 49"},"q":[{"src":"brief","b":2,"text":"overlapping and interwoven linkages between upwind and downwind States","cite":"572 U.S. 489, 496-497"},{"src":"argument","who":"Mr. Mansinghani","text":"In -- in page 47 of their brief, they -- they acknowledge they've used the 1 percent rule in prior transport orders and -- and in EME Homer."}]},{"t":"case","label":"Garland v. Gonzalez","cite":"596 U.S. 543","y":2022,"id":"2021/20-322","sc":1,"by":{"0":"41"},"q":[{"src":"brief","b":0,"text":"must be read ‘narrowly in order to preserve the primary operation of the provision.’","cite":"596 U.S. 543, 555 n.6"}]},{"t":"case","label":"Harrison v. PPG Indus., Inc.","cite":"446 U.S. 578","y":1980,"id":"1979/78-1918","sc":1,"by":{"0":"5, 22, 27, 38","1":"4, 8, 12, 34","2":"3","3":"8"},"q":[{"src":"brief","b":0,"text":"specifically enumerated provisions of the Act","cite":"446 U.S. 578, 584"},{"src":"brief","b":0,"text":"add[ing] to the list of locally or regionally applicable actions","cite":"446 U.S. at 584"},{"src":"brief","b":1,"text":"clarify some questions relating to venue for review of rules or orders,","cite":"446 U.S. at 590"}]},{"t":"case","label":"Hertz Corp. v. Friend","cite":"559 U.S. 77","y":2010,"id":"2009/08-1107","sc":1,"by":{"0":"30-31","3":"5, 16","4":"3, 17"}},{"t":"case","label":"Humane Soc’y of the U.S. v. U.S. Dep’t of Agric.","cite":"41 F.4th 564","y":2022,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.4th/41/564/","by":{"0":"30"},"q":[{"src":"brief","b":0,"text":"between the publication of a document and its issuance, prescription, or promulgation","cite":"41 F.4th 564, 569"}]},{"t":"case","label":"Husky Int’l Elecs., Inc. v. Ritz","cite":"578 U.S. 355","y":2016,"id":"2015/15-145","sc":1,"by":{"0":"27"},"q":[{"src":"brief","b":0,"text":"When ‘Congress acts to amend a statute, we presume it intends its amendment to have real and substantial effect.’","cite":"578 U.S. 355, 359"}]},{"t":"case","label":"Kentucky v. EPA, __ F.4th __","cite":"2024 WL 5001991","y":2024,"court":"6th Cir. Dec. 6","by":{"0":"23, 25, 31, 33, 41, 43, 45, 51, 52, 55","1":"23, 28, 29, 30, 36, 47, 48, 55, 57"},"q":[{"src":"brief","b":0,"text":"requires the EPA to ‘act’ on each State’s ‘submission’ on a plan-byplan basis.","cite":"2024 WL 5001991"},{"src":"brief","b":0,"text":"look[] to an action’s justification at the start to decide whether the action is national or local.","cite":"2024 WL 5001991"},{"src":"brief","b":1,"text":"[T]he regulations or action must ‘have reference to’ (‘applicable’) the ‘nation as a whole’ (‘nationally’).","cite":"2024 WL 5001991"},{"src":"brief","b":1,"text":"‘authoritative decision’ of the ‘matter at issue,’","cite":"2024 WL 5001991"}]},{"t":"case","label":"Kentucky v. EPA","cite":"2023 WL 11871967","y":2023,"court":"6th Cir. July 25","by":{"0":"14, 24","2":"12"},"q":[{"src":"brief","b":0,"text":"affects only [that State]—that is, it does not concern the nation, let alone any other state.","cite":"2023 WL 11871967"}]},{"t":"case","label":"Lewis-Mota v. Sec’y of Lab.","cite":"469 F.2d 478","y":1972,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/469/478/","by":{"0":"30"},"q":[{"src":"brief","b":0,"text":"the label that the particular agency puts upon its given exercise of administrative power","cite":"469 F.2d 478, 481"}]},{"t":"case","label":"Lockhart v. United States","cite":"577 U.S. 347","y":2016,"id":"2015/14-8358","sc":1,"by":{"0":"38"},"q":[{"src":"brief","b":0,"text":"only to the item directly before it.","cite":"577 U.S. 347, 351"}]},{"t":"case","label":"Milner v. Dep’t of Navy","cite":"562 U.S. 562","y":2011,"id":"2010/09-1163","sc":1,"by":{"0":"26"}},{"t":"case","label":"Nat. Res. Def. Council, Inc. v. Thomas","cite":"838 F.2d 1224","y":1988,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/838/1224/","by":{"0":"35, 36"}},{"t":"case","label":"Nat’l Envtl. Dev. Ass’n’s Clean Air Project v. EPA","cite":"891 F.3d 1041","y":2018,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/891/1041/","by":{"0":"55","2":"17"},"q":[{"src":"brief","b":0,"text":"[I]ntercircuit conflicts in the application of EPA policies caused by inconsistent judicial decisions are inevitable because of the Act’s judicial review provision in § 7607(b)(1).","cite":"891 F.3d 1041, 1050"},{"src":"brief","b":2,"text":"uniform judicial review of regulatory issues of national importance.","cite":"891 F.3d 1041, 1054"}]},{"t":"case","label":"Nat’l Parks Conservation Ass’n v. McCarthy","cite":"816 F.3d 989","y":2016,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/816/989/","by":{"0":"24"}},{"t":"case","label":"OBB Personenverkehr AG v. Sachs","cite":"577 U.S. 27","y":2015,"id":"2015/13-1067","sc":1,"by":{"0":"42"}},{"t":"case","label":"Ohio v. EPA","cite":"603 U.S. 279","y":2024,"url":"https://supreme.justia.com/cases/federal/us/603/279/","sc":1,"by":{"0":"7","1":"6, 7, 8"},"q":[{"src":"brief","b":1,"text":"envisions States and the federal government working together to improve air quality.","cite":"603 U.S. 279, 283"},{"src":"brief","b":1,"text":"emissions in upwind States sometimes affect air quality in downwind States.","cite":"603 U.S. at 283"},{"src":"opinion","who":"Opinion of the Court (Justice Thomas)","text":"[b]ecause air currents can carry pollution across state borders, emissions in upwind States sometimes affect air quality in downwind States.","cite":"603 U. S. 279, 283–284"}]},{"t":"case","label":"Reeder v. FCC","cite":"865 F.2d 1298","y":1989,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/865/1298/","by":{"0":"30"}},{"t":"case","label":"RMS of Ga., LLC v. EPA","cite":"64 F.4th 1368","y":2023,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.4th/64/1368/","by":{"0":"36","2":"24, 26"}},{"t":"case","label":"S. Ill. Power Coop. v. EPA","cite":"863 F.3d 666","y":2017,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/863/666/","by":{"0":"29","2":"19, 20, 26, 27"},"q":[{"src":"brief","b":0,"text":"venue depends entirely on—and is fixed by—the nature of the agency’s action.","cite":"863 F.3d 666, 670"},{"src":"brief","b":2,"text":"[t]he text of the statute leaves no room for an intermediate case.","cite":"863 F.3d at 673"},{"src":"brief","b":2,"text":"introduce[] needless uncertainty into the determination of venue, where the need for clear rules is especially acute.","cite":"863 F.3d at 673"}]},{"t":"case","label":"Sierra Club v. EPA","cite":"47 F.4th 738","y":2022,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.4th/47/738/","by":{"0":"24","2":"25, 26, 34, 48"},"q":[{"src":"brief","b":2,"text":"is committed to the agency’s discretion and thus is unreviewable,","cite":"47 F.4th at 745"},{"src":"brief","b":2,"text":"may weigh any number of considerations","cite":"47 F.4th at 746"}]},{"t":"case","label":"Sierra Club v. EPA","cite":"926 F.3d 844","y":2019,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/926/844/","by":{"0":"23"}},{"t":"case","label":"Sw. Airlines Co. v. Saxon","cite":"596 U.S. 450","y":2022,"url":"https://supreme.justia.com/cases/federal/us/596/450/","sc":1,"by":{"0":"27"}},{"t":"case","label":"Texas Mun. Power Agency v. EPA","cite":"89 F.3d 858","y":1996,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/89/858/","by":{"0":"25"}},{"t":"case","label":"Texas v. EPA","cite":"829 F.3d 405","y":2016,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/829/405/","by":{"0":"46, 51, 52, 55","1":"36","2":"32","3":"13, 17","4":"23"},"q":[{"src":"brief","b":0,"text":"states, not EPA, drive the regulatory process.","cite":"829 F.3d 405, 411"},{"src":"brief","b":0,"text":"[b]ecause the statute speaks of the determinations the action ‘is based on,’ the relevant determinations are those that lie at the core of the agency action.","cite":"829 F.3d at 419"},{"src":"brief","b":1,"text":"face power shortages and grid failures.","cite":"829 F.3d 405, 416–17"}]},{"t":"case","label":"Texas v. EPA","cite":"2023 WL 7204840","y":2023,"court":"5th Cir. May 1","by":{"0":"12, 13","1":"22, 36, 57","2":"12"},"q":[{"src":"brief","b":0,"text":"makes clear that the EPA’s relevant actions for purposes of the present litigation are its various [state plan] denials.","cite":"2023 WL 7204840"},{"src":"brief","b":1,"text":"usually highly fact-bound and particular to the individual State,","cite":"2023 WL 7204840"}]},{"t":"case","label":"Train v. Nat. Res. Def. Council, Inc.","cite":"421 U.S. 60","y":1975,"id":"1974/73-1742","sc":1,"by":{"0":"5, 45","1":"7, 8"},"q":[{"src":"brief","b":0,"text":"whatever mix of emissions limitations [is] best suited to its particular situation.","cite":"421 U.S. 60, 79"},{"src":"brief","b":0,"text":"has no authority to question the wisdom of a State’s choices","cite":"421 U.S. at 79"},{"src":"brief","b":1,"text":"so long as the ultimate effect of [the] State’s choice of emission limitations is compliance with the national standards for ambient air.","cite":"421 U.S. 60, 79"}]},{"t":"case","label":"Travis v. United States","cite":"364 U.S. 631","y":1961,"id":"1960/10","sc":1,"by":{"0":"30","3":"5"},"q":[{"src":"brief","b":0,"text":"the choice of ‘a tribunal favorable’ to it.","cite":"364 U.S. 631, 634"}]},{"t":"case","label":"Union Elec. Co. v. EPA","cite":"427 U.S. 246","y":1976,"id":"1975/74-1542","sc":1,"by":{"0":"4, 24, 45","1":"7, 8, 33"},"q":[{"src":"brief","b":0,"text":"Each State is given wide discretion in formulating its plan.","cite":"427 U.S. 246, 250"},{"src":"brief","b":0,"text":"wide discretion in formulating its plan.","cite":"427 U.S. at 250"},{"src":"argument","who":"Mr. Mansinghani","text":"This Court's landmark Clean Air Act cases, state implementation plan cases, Train and Union Electric, both arose from circuit splits where different circuits were adjudicating different state plans but it touched on cross-cutting issues such as whether variances could be allowed in a state plan or whether EPA had to consider cost or feasibility, technical feasibility, in approving or disapproving a state plan."},{"src":"argument","who":"Mr. Mansinghani","text":"It's not the types of things that led to this -- this Court's cases in Train and Union Electric, where you have an intense mix of very local issues and perhaps some cross-cutting issues that may be true across different states."}]},{"t":"case","label":"W. Virginia Chamber of Com. v. Browner","cite":"166 F.3d 336","y":1998,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/166/336/","by":{"0":"26","2":"24, 30"}},{"t":"case","label":"West Virginia v. EPA","cite":"90 F.4th 323","y":2024,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.4th/90/323/","by":{"0":"41, 43, 51","1":"22, 27, 55, 57","2":"12","4":"18, 22"},"q":[{"src":"brief","b":0,"text":"purportedly applies a national standard created by the national statute and its national regulations.","cite":"90 F.4th at 329"},{"src":"brief","b":0,"text":"Were that the appropriate consideration, there could be no local or regional action.","cite":"90 F.4th at 328"},{"src":"brief","b":1,"text":"geographical aspects of the factual and analytical circumstances of the agency’s determination","cite":"90 F.4th at 328"},{"src":"brief","b":1,"text":"if application of a national standard to disapprove a plan were the controlling factor, there never could be a local or regional action as recognized by the Clean Air Act because every action of the EPA purportedly applies a national standard.","cite":"90 F.4th at 329"},{"src":"opinion","who":"Opinion of the Court (Justice Thomas)","text":"giving a unique mixture of reasons,","cite":"90 F. 4th 323, 330"}]},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"3","1":"5"}},{"t":"usc","label":"28 U.S.C. § 2101","url":"https://www.law.cornell.edu/uscode/text/28/2101","subs":["(e)"],"by":{"0":"3"}},{"t":"usc","label":"42 U.S.C. § 7407","url":"https://www.law.cornell.edu/uscode/text/42/7407","subs":["(a)"],"by":{"0":"4, 24"},"q":[{"src":"brief","b":0,"text":"primary responsibility for assuring air quality.","cite":"42 U.S.C. § 7407(a)"}]},{"t":"usc","label":"42 U.S.C. § 7409","url":"https://www.law.cornell.edu/uscode/text/42/7409","subs":["(a)","(b)"],"stext":{"head":"§7409. National primary and secondary ambient air quality standards","paras":[[0,"(a) Promulgation"],[0,"(1) The Administrator—"],[1,"(A) within 30 days after December 31, 1970, shall publish proposed regulations prescribing a national primary ambient air quality standard and a national secondary ambient air quality standard for each air pollutant for which air quality criteria have been issued prior to such date; and"],[1,"(B) after a reasonable time for interested persons to submit written comments thereon (but no later than 90 days after the initial publication of such proposed standards) shall by regulation promulgate such proposed national primary and secondary ambient air quality standards with such modifications as he deems appropriate."],[0,"(2) With respect to any air pollutant for which air quality criteria are issued after December 31, 1970, the Administrator shall publish, simultaneously with the issuance of such criteria and information, proposed national primary and secondary ambient air quality standards for any such pollutant. The procedure provided for in paragraph (1)(B) of this subsection shall apply to the promulgation of such standards."],[0,"(b) Protection of public health and welfare"],[0,"(1) National primary ambient air quality standards, prescribed under subsection (a) shall be ambient air quality standards the attainment and maintenance of which in the judgment of the Administrator, based on such criteria and allowing an adequate margin of safety, are requisite to protect the public health. Such primary standards may be revised in the same manner as promulgated."],[0,"(2) Any national secondary ambient air quality standard prescribed under subsection (a) shall specify a level of air quality the attainment and maintenance of which in the judgment of the Administrator, based on such criteria, is requisite to protect the public welfare from any known or anticipated adverse effects associated with the presence of such air pollutant in the ambient air. Such secondary standards may be revised in the same manner as promulgated."],[0,"(c) National primary ambient air quality standard for nitrogen dioxide"],[0,"The Administrator shall, not later than one year after August 7, 1977, promulgate a national primary ambient air quality standard for NO2 concentrations over a period of not more than 3 hours unless, based on the criteria issued under section 7408(c) of this title, he finds that there is no significant evidence that such a standard for such a period is requisite to protect public health."],[0,"(d) Review and revision of criteria and standards; independent scientific review committee; appointment; advisory functions"],[0,"(1) Not later than December 31, 1980, and at five-year intervals thereafter, the Administrator shall complete a thorough review of the criteria published under section 7408 of this title and the national ambient air quality standards promulgated under this section and shall make such revisions in such criteria and standards and promulgate such new standards as may be appropriate in accordance with section 7408 of this title and subsection (b) of this section. The Administrator may review and revise criteria or promulgate new standards earlier or more frequently than required under this paragraph."],[0,"(2)(A) The Administrator shall appoint an independent scientific review committee composed of seven members including at least one member of the National Academy of Sciences, one physician, and one person representing State air pollution control agencies."],[0,"(B) Not later than January 1, 1980, and at five-year intervals thereafter, the committee referred to in subparagraph (A) shall complete a review of the criteria published under section 7408 of this title and the national primary and secondary ambient air quality standards promulgated under this section and shall recommend to the Administrator any new national ambient air quality standards and revisions of existing criteria and standards as may be appropriate under section 7408 of this title and subsection (b) of this section."],[0,"(C) Such committee shall also (i) advise the Administrator of areas in which additional knowledge is required to appraise the adequacy and basis of existing, new, or revised national ambient air quality standards, (ii) describe the research efforts necessary to provide the required information, (iii) advise the Administrator on the relative contribution to air pollution concentrations of natural as well as anthropogenic activity, and (iv) advise the Administrator of any adverse public health, welfare, social, economic, or energy effects which may result from various strategies for attainment and maintenance of such national ambient air quality standards."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/7409?type=usc&year=mostrecent&link-type=html"},"by":{"0":"4, 4","1":"6","2":"4"}},{"t":"usc","label":"42 U.S.C. § 7410","url":"https://www.law.cornell.edu/uscode/text/42/7410","subs":["(a)(1)","(a)(2)","(a)(2)(A)","(a)(2)(D)(i)(I)","(c)","(c)(1)","(k)","(k)(1)","(k)(2)","(k)(3)","(k)(1)(B)","(a)","(a)(2)(D)(i)","(a)(2)(E)"],"stext":{"head":"§7410. State implementation plans for national primary and secondary ambient air quality standards","paras":[[0,"(a) Adoption of plan by State; submission to Administrator; content of plan; revision; new sources; indirect source review program; supplemental or intermittent control systems"],[0,"(1) Each State shall, after reasonable notice and public hearings, adopt and submit to the Administrator, within 3 years (or such shorter period as the Administrator may prescribe) after the promulgation of a national primary ambient air quality standard (or any revision thereof) under section 7409 of this title for any air pollutant, a plan which provides for implementation, maintenance, and enforcement of such primary standard in each air quality control region (or portion thereof) within such State. In addition, such State shall adopt and submit to the Administrator (either as a part of a plan submitted under the preceding sentence or separately) within 3 years (or such shorter period as the Administrator may prescribe) after the promulgation of a national ambient air quality secondary standard (or revision thereof), a plan which provides for implementation, maintenance, and enforcement of such secondary standard in each air quality control region (or portion thereof) within such State. Unless a separate public hearing is provided, each State shall consider its plan implementing such secondary standard at the hearing required by the first sentence of this paragraph."],[0,"(2) Each implementation plan submitted by a State under this chapter shall be adopted by the State after reasonable notice and public hearing. Each such plan shall—"],[1,"(A) include enforceable emission limitations and other control measures, means, or techniques (including economic incentives such as fees, marketable permits, and auctions of emissions rights), as well as schedules and timetables for compliance, as may be necessary or appropriate to meet the applicable requirements of this chapter;"],[1,"(B) provide for establishment and operation of appropriate devices, methods, systems, and procedures necessary to—"],[2,"(i) monitor, compile, and analyze data on ambient air quality, and"],[2,"(ii) upon request, make such data available to the Administrator;"],[1,"(C) include a program to provide for the enforcement of the measures described in subparagraph (A), and regulation of the modification and construction of any stationary source within the areas covered by the plan as necessary to assure that national ambient air quality standards are achieved, including a permit program as required in parts C and D;"],[1,"(D) contain adequate provisions—"],[2,"(i) prohibiting, consistent with the provisions of this subchapter, any source or other type of emissions activity within the State from emitting any air pollutant in amounts which will—"],[3,"(I) contribute significantly to nonattainment in, or interfere with maintenance by, any other State with respect to any such national primary or secondary ambient air quality standard, or"],[3,"(II) interfere with measures required to be included in the applicable implementation plan for any other State under part C to prevent significant deterioration of air quality or to protect visibility,"],[2,"(ii) insuring compliance with the applicable requirements of sections 7426 and 7415 of this title (relating to interstate and international pollution abatement);"],[1,"(E) provide (i) necessary assurances that the State (or, except where the Administrator deems inappropriate, the general purpose local government or governments, or a regional agency designated by the State or general purpose local governments for such purpose) will have adequate personnel, funding, and authority under State (and, as appropriate, local) law to carry out such implementation plan (and is not prohibited by any provision of Federal or State law from carrying out such implementation plan or portion thereof), (ii) requirements that the State comply with the requirements respecting State boards under section 7428 of this title, and (iii) necessary assurances that, where the State has relied on a local or regional government, agency, or instrumentality for the implementation of any plan provision, the State has responsibility for ensuring adequate implementation of such plan provision;"],[1,"(F) require, as may be prescribed by the Administrator—"],[2,"(i) the installation, maintenance, and replacement of equipment, and the implementation of other necessary steps, by owners or operators of stationary sources to monitor emissions from such sources,"],[2,"(ii) periodic reports on the nature and amounts of emissions and emissions-related data from such sources, and"],[2,"(iii) correlation of such reports by the State agency with any emission limitations or standards established pursuant to this chapter, which reports shall be available at reasonable times for public inspection;"],[1,"(G) provide for authority comparable to that in section 7603 of this title and adequate contingency plans to implement such authority;"],[1,"(H) provide for revision of such plan—"],[2,"(i) from time to time as may be necessary to take account of revisions of such national primary or secondary ambient air quality standard or the availability of improved or more expeditious methods of attaining such standard, and"],[2,"(ii) except as provided in paragraph (3)(C), whenever the Administrator finds on the basis of information available to the Administrator that the plan is substantially inadequate to attain the national ambient air quality standard which it implements or to otherwise comply with any additional requirements established under this chapter;"],[1,"(I) in the case of a plan or plan revision for an area designated as a nonattainment area, meet the applicable requirements of part D (relating to nonattainment areas);"],[1,"(J) meet the applicable requirements of section 7421 of this title (relating to consultation), section 7427 of this title (relating to public notification), and part C (relating to prevention of significant deterioration of air quality and visibility protection);"],[1,"(K) provide for—"],[2,"(i) the performance of such air quality modeling as the Administrator may prescribe for the purpose of predicting the effect on ambient air quality of any emissions of any air pollutant for which the Administrator has established a national ambient air quality standard, and"],[2,"(ii) the submission, upon request, of data related to such air quality modeling to the Administrator;"],[1,"(L) require the owner or operator of each major stationary source to pay to the permitting authority, as a condition of any permit required under this chapter, a fee sufficient to cover—"],[2,"(i) the reasonable costs of reviewing and acting upon any application for such a permit, and"],[2,"(ii) if the owner or operator receives a permit for such source, the reasonable costs of implementing and enforcing the terms and conditions of any such permit (not including any court costs or other costs associated with any enforcement action),"],[1,"until such fee requirement is superseded with respect to such sources by the Administrator's approval of a fee program under subchapter V; and"],[1,"(M) provide for consultation and participation by local political subdivisions affected by the plan."],[0,"(3)(A) Repealed. Pub. L. 101–549, title I, §101(d)(1), Nov. 15, 1990, 104 Stat. 2409."],[0,"(B) As soon as practicable, the Administrator shall, consistent with the purposes of this chapter and the Energy Supply and Environmental Coordination Act of 1974 [15 U.S.C. 791 et seq.], review each State's applicable implementation plans and report to the State on whether such plans can be revised in relation to fuel burning stationary sources (or persons supplying fuel to such sources) without interfering with the attainment and maintenance of any national ambient air quality standard within the period permitted in this section. If the Administrator determines that any such plan can be revised, he shall notify the State that a plan revision may be submitted by the State. Any plan revision which is submitted by the State shall, after public notice and opportunity for public hearing, be approved by the Administrator if the revision relates only to fuel burning stationary sources (or persons supplying fuel to such sources), and the plan as revised complies with paragraph (2) of this subsection. The Administrator shall approve or disapprove any revision no later than three months after its submission."],[0,"(C) Neither the State, in the case of a plan (or portion thereof) approved under this subsection, nor the Administrator, in the case of a plan (or portion thereof) promulgated under subsection (c), shall be required to revise an applicable implementation plan because one or more exemptions under section 7418 of this title (relating to Federal facilities), enforcement orders under section 7413(d) 1 of this title, suspensions under subsection (f) or (g) (relating to temporary energy or economic authority), orders under section 7419 of this title (relating to primary nonferrous smelters), or extensions of compliance in decrees entered under section 7413(e) 1 of this title (relating to iron- and steel-producing operations) have been granted, if such plan would have met the requirements of this section if no such exemptions, orders, or extensions had been granted."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/7410?type=usc&year=mostrecent&link-type=html"},"by":{"0":"2, 5, 6, 14, 16, 21, 23, 25-28, 31, 39, 4, 7, 23, 23, 4, 7, 53, 23, 5, 23, 23, 23, 23, 23, 23, 5, 23","1":"5, 7, 8, 13, 16, 32, 33, 34, 35, 36, 37, 41, 50, 56","2":"23-25, 4, 23, 4, 36, 36, 36, 36, 36, 36","3":"2, 6, 7","4":"4, 5, 6, 9"},"q":[{"src":"brief","b":1,"text":"contain adequate provisions . . . prohibiting . . . any source or other type of emissions activity within the State from emitting any air pollutant in amounts which will . . . contribute significantly to nonattainment in, or interfere with maintenance by, any other State with respect to any [NAAQS],","cite":"42 U.S.C. § 7410(a)(2)(D)"},{"src":"brief","b":1,"text":"So long as a SIP satisfies the ‘applicable requirements’ of the Act . . . , EPA ‘shall approve’ it within 18 months of its submission.","cite":"42 U.S.C. § 7410(k)(3)"},{"src":"argument","who":"Mr. Mansinghani","text":"Here Section 7410 authorizes EPA to take local action, approval or disapproval of state implementation plans. EPA's position that the form of publication dictates the action's applicability for venue purposes has no basis in the text of the statute and, indeed, is at war with it."}]},{"t":"usc","label":"42 U.S.C. § 7411","url":"https://www.law.cornell.edu/uscode/text/42/7411","subs":["(d)","(j)"],"by":{"0":"6, 25, 5, 6, 25"}},{"t":"usc","label":"42 U.S.C. § 7412","url":"https://www.law.cornell.edu/uscode/text/42/7412","by":{"0":"6, 22, 25"}},{"t":"usc","label":"42 U.S.C. § 7419","url":"https://www.law.cornell.edu/uscode/text/42/7419","by":{"0":"6, 25, 31"}},{"t":"usc","label":"42 U.S.C. § 7420","url":"https://www.law.cornell.edu/uscode/text/42/7420","by":{"0":"25"}},{"t":"usc","label":"42 U.S.C. § 7521","url":"https://www.law.cornell.edu/uscode/text/42/7521","by":{"0":"6, 25"}},{"t":"usc","label":"42 U.S.C. § 7607","url":"https://www.law.cornell.edu/uscode/text/42/7607","subs":["(a)(1)","(b)(1)","(a)","(b)(1)(1970)","(d)(9)(A)"],"stext":{"head":"§7607. Administrative proceedings and judicial review","paras":[[0,"(a) Administrative subpenas; confidentiality; witnesses"],[0,"In connection with any determination under section 7410(f) of this title, or for purposes of obtaining information under section 7521(b)(4) 1 or 7545(c)(3) of this title, any investigation, monitoring, reporting requirement, entry, compliance inspection, or administrative enforcement proceeding under the 2 chapter (including but not limited to section 7413, section 7414, section 7420, section 7429, section 7477, section 7524, section 7525, section 7542, section 7603, or section 7606 of this title),,3 the Administrator may issue subpenas for the attendance and testimony of witnesses and the production of relevant papers, books, and documents, and he may administer oaths. Except for emission data, upon a showing satisfactory to the Administrator by such owner or operator that such papers, books, documents, or information or particular part thereof, if made public, would divulge trade secrets or secret processes of such owner or operator, the Administrator shall consider such record, report, or information or particular portion thereof confidential in accordance with the purposes of section 1905 of title 18, except that such paper, book, document, or information may be disclosed to other officers, employees, or authorized representatives of the United States concerned with carrying out this chapter, to persons carrying out the National Academy of Sciences' study and investigation provided for in section 7521(c) of this title, or when relevant in any proceeding under this chapter. Witnesses summoned shall be paid the same fees and mileage that are paid witnesses in the courts of the United States. In case of contumacy or refusal to obey a subpena served upon any person under this subparagraph,4 the district court of the United States for any district in which such person is found or resides or transacts business, upon application by the United States and after notice to such person, shall have jurisdiction to issue an order requiring such person to appear and give testimony before the Administrator to appear and produce papers, books, and documents before the Administrator, or both, and any failure to obey such order of the court may be punished by such court as a contempt thereof."],[0,"(b) Judicial review"],[0,"(1) A petition for review of action of the Administrator in promulgating any national primary or secondary ambient air quality standard, any emission standard or requirement under section 7412 of this title, any standard of performance or requirement under section 7411 of this title,,3 any standard under section 7521 of this title (other than a standard required to be prescribed under section 7521(b)(1) of this title), any determination under section 7521(b)(5) 1 of this title, any control or prohibition under section 7545 of this title, any standard under section 7571 of this title, any rule issued under section 7413, 7419, or under section 7420 of this title, or any other nationally applicable regulations promulgated, or final action taken, by the Administrator under this chapter may be filed only in the United States Court of Appeals for the District of Columbia. A petition for review of the Administrator's action in approving or promulgating any implementation plan under section 7410 of this title or section 7411(d) of this title, any order under section 7411(j) of this title, under section 7412 of this title, under section 7419 of this title, or under section 7420 of this title, or his action under section 1857c–10(c)(2)(A), (B), or (C) of this title (as in effect before August 7, 1977) or under regulations thereunder, or revising regulations for enhanced monitoring and compliance certification programs under section 7414(a)(3) of this title, or any other final action of the Administrator under this chapter (including any denial or disapproval by the Administrator under subchapter I) which is locally or regionally applicable may be filed only in the United States Court of Appeals for the appropriate circuit. Notwithstanding the preceding sentence a petition for review of any action referred to in such sentence may be filed only in the United States Court of Appeals for the District of Columbia if such action is based on a determination of nationwide scope or effect and if in taking such action the Administrator finds and publishes that such action is based on such a determination. Any petition for review under this subsection shall be filed within sixty days from the date notice of such promulgation, approval, or action appears in the Federal Register, except that if such petition is based solely on grounds arising after such sixtieth day, then any petition for review under this subsection shall be filed within sixty days after such grounds arise. The filing of a petition for reconsideration by the Administrator of any otherwise final rule or action shall not affect the finality of such rule or action for purposes of judicial review nor extend the time within which a petition for judicial review of such rule or action under this section may be filed, and shall not postpone the effectiveness of such rule or action."],[0,"(2) Action of the Administrator with respect to which review could have been obtained under paragraph (1) shall not be subject to judicial review in civil or criminal proceedings for enforcement. Where a final decision by the Administrator defers performance of any nondiscretionary statutory action to a later time, any person may challenge the deferral pursuant to paragraph (1)."],[0,"(c) Additional evidence"],[0,"In any judicial proceeding in which review is sought of a determination under this chapter required to be made on the record after notice and opportunity for hearing, if any party applies to the court for leave to adduce additional evidence, and shows to the satisfaction of the court that such additional evidence is material and that there were reasonable grounds for the failure to adduce such evidence in the proceeding before the Administrator, the court may order such additional evidence (and evidence in rebuttal thereof) to be taken before the Administrator, in such manner and upon such terms and conditions as to 5 the court may deem proper. The Administrator may modify his findings as to the facts, or make new findings, by reason of the additional evidence so taken and he shall file such modified or new findings, and his recommendation, if any, for the modification or setting aside of his original determination, with the return of such additional evidence."],[0,"(d) Rulemaking"],[0,"(1) This subsection applies to—"],[1,"(A) the promulgation or revision of any national ambient air quality standard under section 7409 of this title,"],[1,"(B) the promulgation or revision of an implementation plan by the Administrator under section 7410(c) of this title,"],[1,"(C) the promulgation or revision of any standard of performance under section 7411 of this title, or emission standard or limitation under section 7412(d) of this title, any standard under section 7412(f) of this title, or any regulation under section 7412(g)(1)(D) and (F) 6 of this title, or any regulation under section 7412(m) or (n) of this title,"],[1,"(D) the promulgation of any requirement for solid waste combustion under section 7429 of this title,"],[1,"(E) the promulgation or revision of any regulation pertaining to any fuel or fuel additive under section 7545 of this title,"],[1,"(F) the promulgation or revision of any aircraft emission standard under section 7571 of this title,"],[1,"(G) the promulgation or revision of any regulation under subchapter IV–A (relating to control of acid deposition),"],[1,"(H) promulgation or revision of regulations pertaining to primary nonferrous smelter orders under section 7419 of this title (but not including the granting or denying of any such order),"],[1,"(I) promulgation or revision of regulations under subchapter VI (relating to stratosphere and ozone protection),"],[1,"(J) promulgation or revision of regulations under part C of subchapter I (relating to prevention of significant deterioration of air quality and protection of visibility),"],[1,"(K) promulgation or revision of regulations under section 7521 of this title and test procedures for new motor vehicles or engines under section 7525 of this title, and the revision of a standard under section 7521(a)(3) of this title,"],[1,"(L) promulgation or revision of regulations for noncompliance penalties under section 7420 of this title,"],[1,"(M) promulgation or revision of any regulations promulgated under section 7541 of this title (relating to warranties and compliance by vehicles in actual use),"],[1,"(N) action of the Administrator under section 7426 of this title (relating to interstate pollution abatement),"],[1,"(O) the promulgation or revision of any regulation pertaining to consumer and commercial products under section 7511b(e) of this title,"],[1,"(P) the promulgation or revision of any regulation pertaining to field citations under section 7413(d)(3) of this title,"],[1,"(Q) the promulgation or revision of any regulation pertaining to urban buses or the clean-fuel vehicle, clean-fuel fleet, and clean fuel programs under part C of subchapter II,"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/7607?type=usc&year=mostrecent&link-type=html"},"by":{"0":"26, 36, 38, 15, 25-29, 31, 32, 35-40, 42-45, 54, 55","1":"1, 3, 5, 8, 9, 10, 23, 24, 25, 26, 28, 29, 30, 31, 32, 33, 34, 35, 36, 42, 44, 45, 46, 47, 48, 49, 50, 51, 53, 56","2":"30, 15, 38, 3, 33, 38, 33, 38","3":"2, 3, 4, 6, 7, 8, 9, 11, 12, 13, 14, 16, 18, 20, 22","4":"4, 6, 7, 8, 9, 10, 12, 13, 14, 15, 17, 21"},"q":[{"src":"brief","b":1,"text":"promulgating any national primary or secondary ambient air quality standard.","cite":"42 U.S.C. § 7607(b)(1)"},{"src":"brief","b":1,"text":"finds and publishes that such action is based on such a determination.","cite":"42 U.S.C. § 7607(b)(1)"},{"src":"brief","b":2,"text":"only in the United States Court of Appeals for the District of Columbia.","cite":"42 U.S.C. 7607(b)(1)"},{"src":"brief","b":2,"text":"is based on a determination of nationwide scope or effect.","cite":"42 U.S.C. 7607(b)(1)"},{"src":"brief","b":4,"text":"finds and publishes that such action is based on such a determination.","cite":"42 U.S.C. § 7607(b)(1)"}]},{"t":"reg","label":"41 Fed. Reg. 56,767","url":"https://www.govinfo.gov/link/fr/41/56767","by":{"0":"43, 46","1":"10, 11, 12, 37","2":"16, 40, 43, 45","3":"14, 15, 16"}},{"t":"reg","label":"78 Fed. Reg. 5,666","url":"https://www.govinfo.gov/link/fr/78/5666","by":{"0":"30"}},{"t":"reg","label":"80 Fed. Reg. 65,292","url":"https://www.govinfo.gov/link/fr/80/65292","by":{"0":"7","1":"13","2":"5"}},{"t":"reg","label":"85 Fed. Reg. 20,165","url":"https://www.govinfo.gov/link/fr/85/20165","by":{"0":"28","2":"25"}},{"t":"reg","label":"85 Fed. Reg. 65,722","url":"https://www.govinfo.gov/link/fr/85/65722","by":{"0":"50"}},{"t":"reg","label":"86 Fed. Reg. 68,413","url":"https://www.govinfo.gov/link/fr/86/68413","by":{"0":"28","2":"25, 26","3":"9"}},{"t":"reg","label":"87 Fed. Reg. 9,798","url":"https://www.govinfo.gov/link/fr/87/9798","by":{"0":"10, 33, 34, 47, 53","1":"16, 17, 18, 38, 39, 40, 42, 52"}},{"t":"reg","label":"87 Fed. Reg. 22,463","url":"https://www.govinfo.gov/link/fr/87/22463","by":{"0":"9, 31"}},{"t":"reg","label":"87 Fed. Reg. 31,470","url":"https://www.govinfo.gov/link/fr/87/31470","by":{"0":"9","1":"16, 17, 38, 39, 42","3":"19, 20, 24"}},{"t":"reg","label":"88 Fed. Reg. 9,336","url":"https://www.govinfo.gov/link/fr/88/9336","by":{"0":"40, 44, 47, 49, 50-54","1":"5, 18, 19, 20, 32, 38, 39, 40, 42, 43, 46, 49, 50, 53, 54, 55, 56","2":"4, 6-9, 30, 31, 34-37, 44, 47","3":"9, 12, 19, 20, 21, 23, 24","4":"10, 14"}},{"t":"reg","label":"89 Fed. Reg. 12,666","url":"https://www.govinfo.gov/link/fr/89/12666","by":{"0":"9, 31"}},{"t":"reg","label":"89 Fed. Reg. 95,117","url":"https://www.govinfo.gov/link/fr/89/95117","by":{"0":"32"}},{"t":"law","label":"Pub. L. No. 91-604","by":{"0":"37","1":"10"}},{"t":"law","label":"Pub. L. No. 95-95","by":{"0":"6, 27","1":"11, 12","2":"3","4":"13"}},{"t":"law","label":"Pub. L. No. 95-190","by":{"0":"6, 27","1":"12"}},{"t":"case","label":"Corley v. United States","cite":"556 U.S. 303","y":2009,"id":"2008/07-10441","sc":1,"by":{"1":"45, 46, 55"}},{"t":"case","label":"Dayton Power & Light Co. v. EPA","cite":"520 F.2d 703","y":1975,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/520/703/","by":{"1":"11","3":"15"},"q":[{"src":"argument","who":"Mr. Mansinghani","text":"The Dayton Power case from the Sixth Circuit was the other case that -- that led to -- at least according to the legislation history, the enactment of this exception."},{"src":"argument","who":"Mr. Mansinghani","text":"Couple that with the types of cases that we talked about like the NRDC cases and Dayton Power cases and the fact that this is a venue clause, so it shouldn't be manipulable, and the fact that it's an exception, so it shouldn't be read to swallow the rule."}]},{"t":"case","label":"Dep’t of Homeland Sec. v. Regents of the Univ. of Cal.","cite":"591 U.S. 1","y":2020,"url":"https://supreme.justia.com/cases/federal/us/591/1/","sc":1,"by":{"1":"56, 57"}},{"t":"case","label":"Diaz v. United States","cite":"602 U.S. 526","y":2024,"id":"2023/23-14","sc":1,"by":{"1":"55"}},{"t":"case","label":"Fischer v. United States","cite":"603 U.S. 480","y":2024,"id":"2023/23-5572","sc":1,"by":{"1":"31"}},{"t":"case","label":"Garland v. Aleman Gonzalez","cite":"596 U.S. 543","y":2022,"url":"https://supreme.justia.com/cases/federal/us/596/543/","sc":1,"by":{"1":"47"}},{"t":"case","label":"Motor Vehicle Mfrs. Ass’n of U.S., Inc. v. State Farm Mut. Auto. Ins. Co.","cite":"463 U.S. 29","y":1983,"id":"1982/82-354","sc":1,"by":{"1":"45"}},{"t":"case","label":"Nat’l Cable & Telecomms. Ass’n v. Brand X Internet Servs.","cite":"545 U.S. 967","y":2005,"id":"2004/04-277","sc":1,"by":{"1":"45","4":"18"}},{"t":"case","label":"NFIB v. Dep’t of Lab., Occupational Safety & Health Admin.","cite":"595 U.S. 109","y":2022,"url":"https://supreme.justia.com/cases/federal/us/595/109/","sc":1,"by":{"1":"31"},"q":[{"src":"brief","b":1,"text":"Administrative agencies are creatures of statute,","cite":"595 U.S. 109, 117"}]},{"t":"case","label":"NRDC v. EPA","cite":"465 F.2d 492","y":1972,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/465/492/","by":{"1":"11","2":"39","3":"15"},"q":[{"src":"brief","b":2,"text":"litigation in several circuits, with possible inconsistent and delayed results on the merits, can only serve to frustrate the strong Congressional interest in improving the environment.","cite":"465 F.2d 492, 495"},{"src":"argument","who":"Mr. Mansinghani","text":"But the NRDC case -- cases from the First and D.C. Circuits that Mr. Stewart mentioned, the -- the First Circuit said it involved an automatic application of standard nationwide guidelines to all plans that simultaneously preordained wholesale extensions of the -- of the attainment deadline."},{"src":"argument","who":"Mr. Stewart","text":"The second thing I would say, and this goes back to the -- the NRDC cases that I mentioned earlier, that when Congress was studying the venue provision in -- in preparation for the 1977 amendments, it had in mind the SIP approval actions that had taken place and been challenged in many -- in NRDC cases."},{"src":"argument","who":"Mr. Mansinghani","text":"Couple that with the types of cases that we talked about like the NRDC cases and Dayton Power cases and the fact that this is a venue clause, so it shouldn't be manipulable, and the fact that it's an exception, so it shouldn't be read to swallow the rule."}]},{"t":"case","label":"Oklahoma v. EPA","cite":"93 F.4th 1262","y":2024,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.4th/93/1262/","by":{"1":"5"}},{"t":"case","label":"West Virginia v. EPA","cite":"597 U.S. 697","y":2022,"url":"https://supreme.justia.com/cases/federal/us/597/697/","sc":1,"by":{"1":"6, 7, 31"},"q":[{"src":"brief","b":1,"text":"represents ‘the maximum airborne concentration of the pollutant that the public health can tolerate.’","cite":"597 U.S. at 707"},{"src":"brief","b":1,"text":"[a]gencies have only those powers given to them by Congress,","cite":"597 U.S. at 723"},{"src":"opinion","who":"Opinion of the Court (Justice Thomas)","text":"represents `the maximum airborne concentration of [a] pollutant that the public health can tolerate.'","cite":"597 U. S. 697, 707"}]},{"t":"case","label":"Whitman v. Am. Trucking Ass’n, Inc.","cite":"531 U.S. 457","y":2001,"id":"2000/99-1257","sc":1,"by":{"1":"6","2":"19, 22","4":"6"},"q":[{"src":"brief","b":2,"text":"is meant to cover comprehensively every manner in which an agency may exercise its power.","cite":"531 U.S. 457, 478"},{"src":"brief","b":4,"text":"manner[s] in which an agency may exercise its power,","cite":"531 U.S. 457, 478"}]},{"t":"case","label":"Yellen v. Confederated Tribes of Chehalis Rsrv.","cite":"594 U.S. 338","y":2021,"id":"2020/20-543","sc":1,"by":{"1":"30","4":"7"}},{"t":"usc","label":"5 U.S.C. § 551","url":"https://www.law.cornell.edu/uscode/text/5/551","stext":{"head":"§551. Definitions","paras":[[0,"For the purpose of this subchapter—"],[1,"(1) \"agency\" means each authority of the Government of the United States, whether or not it is within or subject to review by another agency, but does not include—"],[2,"(A) the Congress;"],[2,"(B) the courts of the United States;"],[2,"(C) the governments of the territories or possessions of the United States;"],[2,"(D) the government of the District of Columbia;"],[1,"or except as to the requirements of section 552 of this title—"],[2,"(E) agencies composed of representatives of the parties or of representatives of organizations of the parties to the disputes determined by them;"],[2,"(F) courts martial and military commissions;"],[2,"(G) military authority exercised in the field in time of war or in occupied territory; or"],[2,"(H) functions conferred by sections 1738, 1739, 1743, and 1744 of title 12; subchapter II of chapter 471 of title 49; or sections 1884, 1891–1902, and former section 1641(b)(2), of title 50, appendix; 1"],[1,"(2) \"person\" includes an individual, partnership, corporation, association, or public or private organization other than an agency;"],[1,"(3) \"party\" includes a person or agency named or admitted as a party, or properly seeking and entitled as of right to be admitted as a party, in an agency proceeding, and a person or agency admitted by an agency as a party for limited purposes;"],[1,"(4) \"rule\" means the whole or a part of an agency statement of general or particular applicability and future effect designed to implement, interpret, or prescribe law or policy or describing the organization, procedure, or practice requirements of an agency and includes the approval or prescription for the future of rates, wages, corporate or financial structures or reorganizations thereof, prices, facilities, appliances, services or allowances therefor or of valuations, costs, or accounting, or practices bearing on any of the foregoing;"],[1,"(5) \"rule making\" means agency process for formulating, amending, or repealing a rule;"],[1,"(6) \"order\" means the whole or a part of a final disposition, whether affirmative, negative, injunctive, or declaratory in form, of an agency in a matter other than rule making but including licensing;"],[1,"(7) \"adjudication\" means agency process for the formulation of an order;"],[1,"(8) \"license\" includes the whole or a part of an agency permit, certificate, approval, registration, charter, membership, statutory exemption or other form of permission;"],[1,"(9) \"licensing\" includes agency process respecting the grant, renewal, denial, revocation, suspension, annulment, withdrawal, limitation, amendment, modification, or conditioning of a license;"],[1,"(10) \"sanction\" includes the whole or a part of an agency—"],[2,"(A) prohibition, requirement, limitation, or other condition affecting the freedom of a person;"],[2,"(B) withholding of relief;"],[2,"(C) imposition of penalty or fine;"],[2,"(D) destruction, taking, seizure, or withholding of property;"],[2,"(E) assessment of damages, reimbursement, restitution, compensation, costs, charges, or fees;"],[2,"(F) requirement, revocation, or suspension of a license; or"],[2,"(G) taking other compulsory or restrictive action;"],[1,"(11) \"relief\" includes the whole or a part of an agency—"],[2,"(A) grant of money, assistance, license, authority, exemption, exception, privilege, or remedy;"],[2,"(B) recognition of a claim, right, immunity, privilege, exemption, or exception; or"],[2,"(C) taking of other action on the application or petition of, and beneficial to, a person;"],[1,"(12) \"agency proceeding\" means an agency process as defined by paragraphs (5), (7), and (9) of this section;"],[1,"(13) \"agency action\" includes the whole or a part of an agency rule, order, license, sanction, relief, or the equivalent or denial thereof, or failure to act; and"],[1,"(14) \"ex parte communication\" means an oral or written communication not on the public record with respect to which reasonable prior notice to all parties is not given, but it shall not include requests for status reports on any matter or proceeding covered by this subchapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/551?type=usc&year=mostrecent&link-type=html"},"by":{"1":"47","4":"20"}},{"t":"usc","label":"42 U.S.C. § 7401","url":"https://www.law.cornell.edu/uscode/text/42/7401","by":{"1":"6, 30","2":"2"}},{"t":"usc","label":"42 U.S.C. § 7408","url":"https://www.law.cornell.edu/uscode/text/42/7408","stext":{"head":"§7408. Air quality criteria and control techniques","paras":[[0,"(a) Air pollutant list; publication and revision by Administrator; issuance of air quality criteria for air pollutants"],[0,"(1) For the purpose of establishing national primary and secondary ambient air quality standards, the Administrator shall within 30 days after December 31, 1970, publish, and shall from time to time thereafter revise, a list which includes each air pollutant—"],[1,"(A) emissions of which, in his judgment, cause or contribute to air pollution which may reasonably be anticipated to endanger public health or welfare;"],[1,"(B) the presence of which in the ambient air results from numerous or diverse mobile or stationary sources; and"],[1,"(C) for which air quality criteria had not been issued before December 31, 1970 but for which he plans to issue air quality criteria under this section."],[0,"(2) The Administrator shall issue air quality criteria for an air pollutant within 12 months after he has included such pollutant in a list under paragraph (1). Air quality criteria for an air pollutant shall accurately reflect the latest scientific knowledge useful in indicating the kind and extent of all identifiable effects on public health or welfare which may be expected from the presence of such pollutant in the ambient air, in varying quantities. The criteria for an air pollutant, to the extent practicable, shall include information on—"],[1,"(A) those variable factors (including atmospheric conditions) which of themselves or in combination with other factors may alter the effects on public health or welfare of such air pollutant;"],[1,"(B) the types of air pollutants which, when present in the atmosphere, may interact with such pollutant to produce an adverse effect on public health or welfare; and"],[1,"(C) any known or anticipated adverse effects on welfare."],[0,"(b) Issuance by Administrator of information on air pollution control techniques; standing consulting committees for air pollutants; establishment; membership"],[0,"(1) Simultaneously with the issuance of criteria under subsection (a), the Administrator shall, after consultation with appropriate advisory committees and Federal departments and agencies, issue to the States and appropriate air pollution control agencies information on air pollution control techniques, which information shall include data relating to the cost of installation and operation, energy requirements, emission reduction benefits, and environmental impact of the emission control technology. Such information shall include such data as are available on available technology and alternative methods of prevention and control of air pollution. Such information shall also include data on alternative fuels, processes, and operating methods which will result in elimination or significant reduction of emissions."],[0,"(2) In order to assist in the development of information on pollution control techniques, the Administrator may establish a standing consulting committee for each air pollutant included in a list published pursuant to subsection (a)(1), which shall be comprised of technically qualified individuals representative of State and local governments, industry, and the academic community. Each such committee shall submit, as appropriate, to the Administrator information related to that required by paragraph (1)."],[0,"(c) Review, modification, and reissuance of criteria or information"],[0,"The Administrator shall from time to time review, and, as appropriate, modify, and reissue any criteria or information on control techniques issued pursuant to this section. Not later than six months after August 7, 1977, the Administrator shall revise and reissue criteria relating to concentrations of NO2 over such period (not more than three hours) as he deems appropriate. Such criteria shall include a discussion of nitric and nitrous acids, nitrites, nitrates, nitrosamines, and other carcinogenic and potentially carcinogenic derivatives of oxides of nitrogen."],[0,"(d) Publication in Federal Register; availability of copies for general public"],[0,"The issuance of air quality criteria and information on air pollution control techniques shall be announced in the Federal Register and copies shall be made available to the general public."],[0,"(e) Transportation planning and guidelines"],[0,"The Administrator shall, after consultation with the Secretary of Transportation, and after providing public notice and opportunity for comment, and with State and local officials, within nine months after November 15, 1990,1 and periodically thereafter as necessary to maintain a continuous transportation-air quality planning process, update the June 1978 Transportation-Air Quality Planning Guidelines and publish guidance on the development and implementation of transportation and other measures necessary to demonstrate and maintain attainment of national ambient air quality standards. Such guidelines shall include information on—"],[1,"(1) methods to identify and evaluate alternative planning and control activities;"],[1,"(2) methods of reviewing plans on a regular basis as conditions change or new information is presented;"],[1,"(3) identification of funds and other resources necessary to implement the plan, including interagency agreements on providing such funds and resources;"],[1,"(4) methods to assure participation by the public in all phases of the planning process; and"],[1,"(5) such other methods as the Administrator determines necessary to carry out a continuous planning process."],[0,"(f) Information regarding processes, procedures, and methods to reduce or control pollutants in transportation; reduction of mobile source related pollutants; reduction of impact on public health"],[0,"(1) The Administrator shall publish and make available to appropriate Federal, State, and local environmental and transportation agencies not later than one year after November 15, 1990, and from time to time thereafter—"],[1,"(A) information prepared, as appropriate, in consultation with the Secretary of Transportation, and after providing public notice and opportunity for comment, regarding the formulation and emission reduction potential of transportation control measures related to criteria pollutants and their precursors, including, but not limited to—"],[2,"(i) programs for improved public transit;"],[2,"(ii) restriction of certain roads or lanes to, or construction of such roads or lanes for use by, passenger buses or high occupancy vehicles;"],[2,"(iii) employer-based transportation management plans, including incentives;"],[2,"(iv) trip-reduction ordinances;"],[2,"(v) traffic flow improvement programs that achieve emission reductions;"],[2,"(vi) fringe and transportation corridor parking facilities serving multiple occupancy vehicle programs or transit service;"],[2,"(vii) programs to limit or restrict vehicle use in downtown areas or other areas of emission concentration particularly during periods of peak use;"],[2,"(viii) programs for the provision of all forms of high-occupancy, shared-ride services;"],[2,"(ix) programs to limit portions of road surfaces or certain sections of the metropolitan area to the use of non-motorized vehicles or pedestrian use, both as to time and place;"],[2,"(x) programs for secure bicycle storage facilities and other facilities, including bicycle lanes, for the convenience and protection of bicyclists, in both public and private areas;"],[2,"(xi) programs to control extended idling of vehicles;"],[2,"(xii) programs to reduce motor vehicle emissions, consistent with subchapter II, which are caused by extreme cold start conditions;"],[2,"(xiii) employer-sponsored programs to permit flexible work schedules;"],[2,"(xiv) programs and ordinances to facilitate non-automobile travel, provision and utilization of mass transit, and to generally reduce the need for single-occupant vehicle travel, as part of transportation planning and development efforts of a locality, including programs and ordinances applicable to new shopping centers, special events, and other centers of vehicle activity;"],[2,"(xv) programs for new construction and major reconstructions of paths, tracks or areas solely for the use by pedestrian or other non-motorized means of transportation when economically feasible and in the public interest. For purposes of this clause, the Administrator shall also consult with the Secretary of the Interior; and"],[2,"(xvi) program to encourage the voluntary removal from use and the marketplace of pre-1980 model year light duty vehicles and pre-1980 model light duty trucks.2"],[1,"(B) information on additional methods or strategies that will contribute to the reduction of mobile source related pollutants during periods in which any primary ambient air quality standard will be exceeded and during episodes for which an air pollution alert, warning, or emergency has been declared;"],[1,"(C) information on other measures which may be employed to reduce the impact on public health or protect the health of sensitive or susceptible individuals or groups; and"],[1,"(D) information on the extent to which any process, procedure, or method to reduce or control such air pollutant may cause an increase in the emissions or formation of any other pollutant."],[0,"(2) In publishing such information the Administrator shall also include an assessment of—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/7408?type=usc&year=mostrecent&link-type=html"},"by":{"1":"6","2":"4"},"q":[{"src":"brief","b":1,"text":"‘may reasonably be anticipated to endanger public health or welfare,’ and ‘the presence of which in the ambient air results from numerous or diverse mobile or stationary sources.’","cite":"42 U.S.C. § 7408(a)(1)"}]},{"t":"rule","label":"Fed. R. App. P. 15","url":"https://www.law.cornell.edu/rules/frap/rule_15","by":{"1":"42"}},{"t":"reg","label":"82 Fed. Reg. 1,733","url":"https://www.govinfo.gov/link/fr/82/1733","by":{"1":"15"}},{"t":"reg","label":"84 Fed. Reg. 66,612","url":"https://www.govinfo.gov/link/fr/84/66612","by":{"1":"15"}},{"t":"case","label":"(III) Cases—Continued: Bostock v. Clayton County","cite":"590 U.S. 644","y":2020,"url":"https://supreme.justia.com/cases/federal/us/590/644/","sc":1,"by":{"2":"31, 32, 45"}},{"t":"case","label":"FCC v. Pottsville Broad. Co.","cite":"309 U.S. 134","y":1940,"id":"scdb/1939-099","sc":1,"by":{"2":"23, 24","4":"10, 11"},"q":[{"src":"brief","b":2,"text":"should be free to fashion their own rules of procedure and to pursue methods of inquiry capable of permitting them to discharge their multitudinous duties.","cite":"309 U.S. 134, 143"},{"src":"brief","b":2,"text":"whether applications should be heard contemporaneously or successively.","cite":"309 U.S. at 138"},{"src":"brief","b":4,"text":"whether applications should be heard contemporaneously or successively,","cite":"309 U.S. at 138"}]},{"t":"case","label":"HollyFrontier Cheyenne Ref., LLC v. Renewable Fuels Ass’n","cite":"594 U.S. 382","y":2021,"id":"2020/20-472","sc":1,"by":{"2":"43"},"q":[{"src":"brief","b":2,"text":"this Court has made clear that statutory exceptions are to be read fairly, not narrowly, for they ‘are no less part of Congress’s work than its rules and standards—and all are worthy of a court’s respect.’","cite":"594 U.S. 382, 395-396"}]},{"t":"case","label":"Hunt Ref. Co. v. EPA","cite":"90 F.4th 1107","y":2024,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.4th/90/1107/","by":{"2":"19"}},{"t":"case","label":"Loper Bright Enterprises v. Raimondo","cite":"603 U.S. 369","y":2024,"id":"2023/22-451","sc":1,"by":{"2":"33","3":"5, 17"},"q":[{"src":"brief","b":3,"text":"courts decide legal questions by applying their own judgment.","cite":"603 U.S. 369, 392"}]},{"t":"case","label":"Marsh v. Oregon Natural Resources Council","cite":"490 U.S. 360","y":1989,"id":"1988/87-1704","sc":1,"by":{"2":"33"}},{"t":"case","label":"National Ass’n of Mfrs. v. Department of Defense","cite":"583 U.S. 109","y":2018,"id":"2017/16-299","sc":1,"by":{"2":"27"}},{"t":"case","label":"Natural Resources Defense Council v. EPA","cite":"475 F.2d 968","y":1973,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/475/968/","by":{"2":"39","3":"15"},"q":[{"src":"brief","b":2,"text":"involve facts or laws peculiar to any one jurisdiction; rather, all concern uniform determinations of nationwide effect made by the Administrator.","cite":"475 F.2d at 970"}]},{"t":"case","label":"North Dakota v. EPA","cite":"730 F.3d 750","y":2013,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/730/750/","by":{"2":"25"}},{"t":"case","label":"Rumsfeld v. Padilla","cite":"542 U.S. 426","y":2004,"id":"2003/03-1027","sc":1,"by":{"2":"20","3":"2"}},{"t":"case","label":"Safeco Ins. Co. of Am. v. Burr","cite":"551 U.S. 47","y":2007,"id":"2006/06-84","sc":1,"by":{"2":"31, 38","4":"17"},"q":[{"src":"brief","b":2,"text":"indicates a but-for causal relationship and thus a necessary logical condition.","cite":"551 U.S. 47, 63"}]},{"t":"case","label":"Texas v. EPA","cite":"2011 WL 710598","y":2011,"court":"5th Cir. Feb. 24","by":{"2":"30"}},{"t":"case","label":"Texas v. EPA","cite":"983 F.3d 826","y":2020,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/983/826/","by":{"2":"34","3":"17"}},{"t":"case","label":"Vermont Yankee Nuclear Power Corp. v. Natural Resources Defense Council","cite":"435 U.S. 519","y":1978,"id":"1977/76-419","sc":1,"by":{"2":"24","4":"10"}},{"t":"case","label":"West Virginia v. EPA","cite":"362 F.3d 861","y":2004,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/362/861/","by":{"2":"5"}},{"t":"case","label":"Wisconsin v. EPA","cite":"938 F.3d 303","y":2019,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/938/303/","by":{"2":"36"}},{"t":"usc","label":"42 U.S.C. § 7511","url":"https://www.law.cornell.edu/uscode/text/42/7511","subs":["(a)(1)"],"by":{"2":"36"}},{"t":"usc","label":"42 U.S.C. § 7545","url":"https://www.law.cornell.edu/uscode/text/42/7545","subs":["(h)(1)","(h)(6)","(k)(1)(A)","(k)(10)(D)"],"by":{"2":"29, 30, 30, 30, 30"}},{"t":"usc","label":"1 U.S.C. § 1","url":"https://www.law.cornell.edu/uscode/text/1/1","stext":{"head":"§1. Words denoting number, gender, and so forth","paras":[[0,"In determining the meaning of any Act of Congress, unless the context indicates otherwise—"],[1,"words importing the singular include and apply to several persons, parties, or things;"],[1,"words importing the plural include the singular;"],[1,"words importing the masculine gender include the feminine as well;"],[1,"words used in the present tense include the future as well as the present;"],[1,"the words \"insane\" and \"insane person\" shall include every idiot, insane person, and person non compos mentis;"],[1,"the words \"person\" and \"whoever\" include corporations, companies, associations, firms, partnerships, societies, and joint stock companies, as well as individuals;"],[1,"\"officer\" includes any person authorized by law to perform the duties of the office;"],[1,"\"signature\" or \"subscription\" includes a mark when the person making the same intended it as such;"],[1,"\"oath\" includes affirmation, and \"sworn\" includes affirmed;"],[1,"\"writing\" includes printing and typewriting and reproductions of visual symbols by photographing, multigraphing, mimeographing, manifolding, or otherwise."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/1/1?type=usc&year=mostrecent&link-type=html"},"by":{"2":"23","4":"9"},"q":[{"src":"brief","b":2,"text":"unless the context indicates otherwise[,] words importing the singular include and apply to several persons, parties, or things.","cite":"1 U.S.C. 1"},{"src":"brief","b":4,"text":"words importing the singular include and apply to several persons, parties, and things,","cite":"1 U.S.C. § 1"}]},{"t":"usc","label":"5 U.S.C. § 706","url":"https://www.law.cornell.edu/uscode/text/5/706","subs":["(2)(A)"],"by":{"2":"33, 38"}},{"t":"usc","label":"42 U.S.C. § 1857h-5","url":"https://www.law.cornell.edu/uscode/text/42/1857h-5","subs":["(b)(1)(1970)"],"by":{"2":"3, 21, 38"}},{"t":"reg","label":"37 Fed. Reg. 10,842","url":"https://www.govinfo.gov/link/fr/37/10842","by":{"2":"39"}},{"t":"reg","label":"63 Fed. Reg. 57,356","url":"https://www.govinfo.gov/link/fr/63/57356","by":{"2":"25"}},{"t":"reg","label":"76 Fed. Reg. 48,208","url":"https://www.govinfo.gov/link/fr/76/48208","by":{"2":"5"}},{"t":"case","label":"Babb v. Wilkie","cite":"589 U.S. 399","y":2020,"id":"2019/18-882","sc":1,"by":{"3":"7"}},{"t":"case","label":"Fry v. Napoleon Cmty. Schs.","cite":"580 U.S. 154","y":2017,"id":"2016/15-497","sc":1,"by":{"3":"13"}},{"t":"case","label":"Kentucky v. EPA","cite":"123 F.4th 447","y":2024,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/123/447/","by":{"3":"4, 9, 15, 17, 18","4":"8, 10, 20"},"q":[{"src":"brief","b":3,"text":"to the activity taken ‘under this chapter,’","cite":"123 F.4th 447, 461"},{"src":"brief","b":3,"text":"word ‘[n]ational’ contemplates an activity with a nationwide scope.’","cite":"123 F.4th at 459"},{"src":"brief","b":4,"text":"contemplates an activity with a nationwide scope,","cite":"123 F.4th 447, 459–60"}]},{"t":"case","label":"Maryland v. EPA","cite":"958 F.3d 1185","y":2020,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/958/1185/","by":{"3":"10"},"q":[{"src":"brief","b":3,"text":"EPA actions approving or promulgating ‘implementation plans which run only to one air quality control region’","cite":"958 F.3d 1185, 1199"}]},{"t":"case","label":"Mohamad v. Palestinian Auth.","cite":"566 U.S. 449","y":2012,"id":"2011/11-88","sc":1,"by":{"3":"8"}},{"t":"case","label":"Navarro Sav. Ass’n v. Lee","cite":"446 U.S. 458","y":1980,"id":"1979/79-465","sc":1,"by":{"3":"6","4":"3, 17, 19"}},{"t":"case","label":"SEC v. Chenery Corp.","cite":"332 U.S. 194","y":1947,"id":"scdb/1946-133","sc":1,"by":{"3":"22","4":"19"},"q":[{"src":"brief","b":3,"text":"a reviewing court … must judge the propriety of such action solely by the grounds invoked by the agency.","cite":"332 U.S. 194, 196"},{"src":"argument","who":"Mr. Mansinghani","text":"So you have a Chenery problem there, and you also have a problem that the statute requires EPA to make a publication. And, of course, this is also a long-standing thing that they've used."}]},{"t":"case","label":"Sierra Club v. EPA","cite":"311 F.3d 853","y":2002,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/311/853/","by":{"3":"10"}},{"t":"reg","label":"40 C.F.R. § 81.18","url":"https://www.ecfr.gov/current/title-40/section-81.18","by":{"3":"10"}},{"t":"reg","label":"40 C.F.R. § 81.44","url":"https://www.ecfr.gov/current/title-40/section-81.44","by":{"3":"10"}},{"t":"reg","label":"66 Fed. Reg. 15,578","url":"https://www.govinfo.gov/link/fr/66/15578","by":{"3":"10"}},{"t":"reg","label":"89 Fed. Reg. 92,816","url":"https://www.govinfo.gov/link/fr/89/92816","by":{"3":"10"}},{"t":"case","label":"Allied-Signal, Inc. v. U.S. Nuclear Regul. Comm’n","cite":"988 F.2d 146","y":1993,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/988/146/","by":{"4":"20"}},{"t":"case","label":"Box v. Planned Parenthood of Ind. & Ky., Inc.","cite":"587 U.S. 490","y":2019,"id":"2018/18-483","sc":1,"by":{"4":"26"}},{"t":"case","label":"Carlson v. Postal Regul. Comm’n","cite":"938 F.3d 337","y":2019,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/938/337/","by":{"4":"20"}},{"t":"case","label":"Dep’t of Comm. v. New York","cite":"588 U.S. 752","y":2019,"url":"https://supreme.justia.com/cases/federal/us/588/752/","sc":1,"by":{"4":"11"}},{"t":"case","label":"K Mart Corp. v. Cartier, Inc.","cite":"486 U.S. 281","y":1988,"id":"1987/86-495","sc":1,"by":{"4":"20"},"q":[{"src":"brief","b":4,"text":"the regulation would not have been passed but for its inclusion.","cite":"486 U.S. 281, 294"}]},{"t":"case","label":"Mercantile Nat’l Bank at Dallas v. Langdeau","cite":"371 U.S. 555","y":1963,"id":"1962/14_0","sc":1,"by":{"4":"3, 11, 17, 19"},"q":[{"src":"brief","b":4,"text":"allow[ ] courts and litigants to quickly and efficiently determine where venue lies,","cite":"371 U.S. at 558"}]},{"t":"case","label":"United States v. Stanchich","cite":"550 F.2d 1294","y":1977,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/550/1294/","by":{"4":"11"}},{"t":"reg","label":"Other Authorities, 88 Fed. Reg. 87,720","url":"https://www.govinfo.gov/link/fr/88/87720","by":{"4":"10"}}]};